{
  "customer": {
    "claims": [
      "I paid full price for goods that arrived visibly damaged and I demand a complete refund.",
      "The seller owes me additional compensation for the time and trouble of dealing with this mess.",
      "The packaging was clearly insufficient and the damage happened before it ever left their hands.",
      "If this isn't resolved immediately I will escalate to every review platform and consumer protection agency available."
    ],
    "noise": [
      "Absolutely pathetic service.",
      "Don't bother making excuses, I've seen them all.",
      "You people are the reason nobody trusts online shops anymore."
    ]
  },
  "vendor": {
    "claims": [
      "Every item was inspected and verified intact before it left our warehouse and we have the records to prove it.",
      "Any damage occurred during transit or after delivery, which is outside our responsibility.",
      "I demand the public accusation be withdrawn and our shop's name cleared immediately.",
      "We will not issue a refund for damage we did not cause and we reserve the right to pursue this further."
    ],
    "noise": [
      "Unbelievable entitlement.",
      "Maybe next time don't leave your package sitting in the rain.",
      "We've been in business for years and this is how you treat us?"
    ]
  }
}

{
  "lender": {
    "claims": [
      "You borrowed $18,000 on March 3rd at 8% interest, and I want every cent of principal plus interest paid now.",
      "The deadline passed five months ago and you haven't sent a single dollar since.",
      "I bailed you out when nobody else would, and now you're trying to rewrite a deal you agreed to.",
      "Wire the full amount by Friday or I'm filing in small claims court and naming you in every group we share."
    ],
    "noise": [
      "Unbelievable.",
      "You always have an excuse.",
      "Everyone here can see exactly what you are."
    ]
  },
  "borrower": {
    "claims": [
      "The actual amount that hit my account was $14,500, not $18,000, and I have the bank statement to prove it.",
      "You never once sent me a written breakdown or statement, so I'm not paying a number you invented.",
      "I'm not refusing to pay, I'm asking for a monthly plan I can actually keep up with.",
      "Messaging me publicly every day and threatening me isn't collecting a debt, it's harassment."
    ],
    "noise": [
      "Calm down.",
      "You're embarrassing yourself.",
      "Keep yelling, see if it helps."
    ]
  }
}
